import * as React from "react"

function SimpleCardLayoutWithImage({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="simple-card-layout-with-image"
      className={className}
      {...props}
    >
      <div className="rounded-xl overflow-hidden flex shadow hover max-w-sm bg-white cursor-pointer h-28">
          <div className="w-7/12 pl-3 p-3 text-text1 flex flex-col justify-center">
              <p className="text-base mb-2 font-bold truncate">Utilities for setting the width of an element</p>
              <div className="text-xs text-primary mb-2">
                  <a className="flex items-center">
                      <img src="https://images.unsplash.com/photo-1477118476589-bff2c5c4cfbb?ixlib=rb-1.2.1&ixid=eyJhcHBfaWQiOjEyMDd9&auto=format&fit=crop&w=200&q=200" className="rounded-full h-8 w-8 mr-2 object-cover" />
                      <span className="font-bold tracking-wide text-sm text-pink-400">Jane Doe</span>
                  </a>
              </div>
              <div className="text-sm text-text2 tracking-wider">Jan 6 | 4 min read</div>
          </div>
          <div className="lg flex w-5/12 p-2">
              <img src="https://source.unsplash.com/1600x900/?nature,water" className="rounded-xl object-cover w-full h-full"/>
          </div>
      </div>
    </div>
  )
}

export { SimpleCardLayoutWithImage }
